    public DelegatingParcelTracker(ConcurrentHashMap<Integer, String> initialPackagePositions) {
        this.packagePositions = new ConcurrentHashMap<>();
        initialPackagePositions.forEach((key, value)-> packagePositions.put(key, value)));
