import java.util.concurrent.*;
public class ParcelMovement {

    private static final int NUM_THREADS = 3;
    private static final long TIMEOUT_MILLIS = 1000;
    private static final TimeUnit TIMEOUT_UNIT = TimeUnit.MILLISECONDS;

    private static ExecutorService executorService;

    public static void main(String[] args) throws InterruptedException, NotEnoughItemsException {
        executorService = Executors.newFixedThreadPool(NUM_THREADS));
        Locker sourceLocker = new Locker("Source Locker");
        Locker targetLocker = new Locker("Target Locker"));
        int totalQuantityToMove = 50;
