        }
        executorService.shutdown();
    }

    private static class ParcelTask implements Runnable {

        private final Locker sourceLocker;
        private final Locker targetLocker;
        private final int quantityToMove;

        public ParcelTask(Locker sourceLocker, Locker targetLocker, int quantityToMove) {
            this.sourceLocker = sourceLocker;
            this.targetLocker = targetLocker;
            this.quantityToMove = quantityToMove;
        }

        @Override
        public void run() {
            tryLock(sourceLocker, TimeoutMillis, TIMEOUT_UNIT));
            if (!tryLock(targetLocker, TimeoutMillis, TIMEOUT_UNIT))) {
                return;
            }
            while (quantityToMove > 0) {
                if (--quantityToMove <= 0) {
                    break;
                }
                // Perform the parcelling operation here
                System.out.println("Moved " + 1 + " item(s) from Source Locker to Target Locker.");
            }
            unlock(targetLocker));
        }

    }

