import java.util.concurrent.*;

public class ParcelMovement {

    private static final int MAX_THREADS = 3;
    private static final ExecutorService executor = Executors.newFixedThreadPool(MAX_THREADS));

    public static void main(String[] args) throws InterruptedException, ExecutionException {

        Locker sourceLocker = new Locker("Source");
        Locker targetLocker = new Locker("Target");

        int totalItems = 100;
        int parcelsToMove = 10;

        int itemsPerParcel = Math.ceil((double) totalItems / (double) parcelsToMove));

        for (int i = 0; i < parcelsToMove; i++) {

            int sourceLockerIndex = i / parcelsToMove * 2 + 1;
            int targetLockerIndex = i / parcelsToMove * 2 + 2;

            Parcel parcel = new Parcel(sourceLockerIndex, targetLockerIndex, itemsPerParcel));
            executor.submit(parcel);
        }

        executor.shutdown();
        while (!executor.isTerminated())) {
            Thread.sleep(100);
        }

        System.out.println("All parcels have been moved successfully.");

    }

    private static class Parcel implements Runnable {

        private final int sourceLockerIndex;
        private final int targetLockerIndex;
        private final int itemsPerParcel;
        private boolean failed = false;

        public Parcel(int sourceLockerIndex, int targetLockerIndex, int itemsPerParcel) {
            this.sourceLockerIndex = sourceLockerIndex;
            this.targetLockerIndex = targetLockerIndex;
            this.itemsPerParcel = itemsPerParcel;
        }

        @Override
        public void run() {

            ReentrantLock sourceLock = new ReentrantLock();
            ReentrantLock targetLock = new ReentrantLock();

            try {

                if (!sourceLock.tryLock(10, TimeUnit.MILLISECONDS)) {
                    throw new IllegalStateException("Failed to acquire the lock on the source locker."));
                }

                if (!targetLock.tryLock(10, TimeUnit.MILLISECONDS)))) {
                    throw new IllegalStateException("Failed to acquire the lock on the target locker."));
                }

                sourceLocker.lock();
                targetLocker.lock();

                int itemsToMove = Math.min(itemsPerParcel, sourceLocker.getItemCount()));
                if (itemsToMove > 0) {
                    System.out.printf("Moving %d item(s) from locker %d to locker %d.%n", itemsToMove, sourceLockerIndex, targetLockerIndex));
                    sourceLocker.moveItems(targetLocker, itemsToMove);
                }

                targetLocker.unlock();
                sourceLocker.unlock();

            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                this.failed = true;
                System.err.println("The current thread has been interrupted."));
            } finally {
                if (!this.failed) {
                    System.out.printf("Successfully moved %d item(s) from locker %d to locker %d.%n", itemsPerParcel, sourceLockerIndex, targetLockerIndex));
                }
            }

        }

    }

    private static class Locker {

        private final String name;
        private int itemCount = 0;
        private int lockedItems = 0;
        private ReentrantLock lock = new ReentrantLock();

        public Locker(String name) {
            this.name = name;
        }

        public void moveItems(Locker target, int itemsToMove) {
            if (itemsToMove > 0 && this != target) {
                int availableItems = itemCount - lockedItems;
                int actualItemsToMove = Math.min(itemsToMove, availableItems));
                itemCount -= actualItemsToMove;
                lockedItems += actualItemsToMove;
                System.out.printf("Moved %d item(s) from locker %d to locker %d.%n", actualItemsToMove, this.name, target.name));
            } else {
                throw new NotEnoughItemsException("The source locker does not have sufficient items for the move."));
            }
        }

        public int getItemCount() {
            return itemCount;
        }

    }

