        ExecutorService executor = Executors.newFixedThreadPool(2));

        try {
            // Acquire origin container lock
            origin.lock().acquire();

            // Attempt to acquire target container lock within the timeout period
            if (!target.lock().tryLock(TIMEOUT_MILLISECONDS, TIMEOUT_TIME_UNIT))) {
                System.out.println("Failed to acquire both container locks within the timeout period.");
                return;
            }

            // Attempt to swap elements between origin and target containers
            if (!swapElements(origin, target, elementsToSwap))) {
                System.out.println("Failed to swap elements between origin and target containers.");
                return;
            }

            // Release both container locks
            origin.lock().release();
            target.lock().release();

            System.out.println("Successfully swapped " + ELEMENTS_TO_SWAP + " elements between origin and target containers.");

