import java.util.Comparator;
import java.util.List;
import java.util.concurrent.*;

enum RuneConstellation {
    EARTH, AIR, WATER, FIRE
}

enum RuneResonance {
    NONE, GENERAL, SPECIAL
}

class RuneHarmony {
    RuneConstellation constellation;
    RuneResonance resonance1;
    RuneResonance resonance2;

    public RuneHarmony(List<Rune> runes) {
        runes.sort(Comparator.comparing(r -> r.constellation, Comparator.nullsLast()))));
        this.constellation = runes.get(0).constellation;
        for (int i = 0; i < runes.size(); i++) {
            if (runes.get(i).constellation == this.constellation) {
                if (this.resonance1 != null && this.resonance2 != null) break;
                if (this.resonance1 == null) this.resonance1 = runes.get(i).resonance;
                else this.resonance2 = runes.get(i).resonance;
            }
        }
    }
}

