import java.util.concurrent.*;

interface Talisman {
    void enchant();
}

class SigilNode implements Callable<SigilNode> {

    private String name;

    public SigilNode(String name) {
        this.name = name;
    }

    @Override
    public SigilNode call() throws Exception {
        if (name.equals("End Node")) {
            return null;
        } else {
            return new SigilNode("Grandchild Node " + ThreadLocalRandom.current().nextInt(10)));
        }
    }

    @Override
    public String toString() {
        return name;
    }
}

public class ConcurrentProgram implements Callable<List<String>>>, Runnable {

    private ExecutorService executor;
    private List<Talisman> talismans;

    public ConcurrentProgram(int numberOfTalismans) throws InterruptedException, ExecutionException {
        this.talismans = new ArrayList<>();
        for (int i = 0; i < numberOfTalismans; i++) {
            Talisman talisman = new Talisman() {
                @Override
                public void enchant() {
                    System.out.println("Enchanting talisman " + ThreadLocalRandom.current().nextInt(10)));
                }
            };
            talismans.add(talisman);
        }

        executor = Executors.newFixedThreadPool(2));
        List<Future<?>> futures = new ArrayList<>();

        for (Talisman talisman : talismans) {
            Future<?> future = executor.submit(talisman);
            futures.add(future);
        }

        for (Future<?> future : futures)) {
            try {
                future.get();
            } catch (InterruptedException | ExecutionException e) {
                e.printStackTrace();
            }
        }

        executor.shutdown();
    }

    @Override
    public void run() {
        try {
            List<String> result = executor.submit(new Callable<List<String>>>() {
                @Override
                public List<String> call() throws Exception {
                    return new ArrayList<>();
                }
            }).get();

            System.out.println("Parallel processing completed successfully. Final result collection: " + result));
        } catch (InterruptedException | ExecutionException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        int numberOfTalismans = 5; // Change this value to test with different number of talismans

        ConcurrentProgram concurrentProgram = new ConcurrentProgram(numberOfTalismans));
        concurrentProgram.run();
    }
}

