import java.util.*;
import java.util.concurrent.*;

public abstract class LLMC {

void processSequentially(List<Element> elements) {
for (Element e : elements)
process(e);
}

void processInParallel(Executor exec, List<Element> elements) {
CountDownLatch latch = new CountDownLatch(elements.size());
for (final Element e : elements) {
exec.execute(() -> {
process(e);
latch.countDown();
});
}
try {
latch.await();
} catch (InterruptedException ie) {
Thread.currentThread().interrupt();
}
}

public abstract void process(Element e);

public <T> void sequentialRecursive(List<Node<T>> nodes, Collection<T> results) {
for (Node<T> n : nodes) {
results.add(n.compute());
sequentialRecursive(n.getChildren(), results);
}
}

public <T> Collection<T> parallelRecursive(List<Node<T>> nodes) throws InterruptedException {
Collection<T> results = Collections.synchronizedList(new ArrayList<>());
CountDownLatch latch = new CountDownLatch(nodes.size());

Thread worker = new Thread(() -> {
for (Node<T> n : nodes) {
T result = n.compute();
results.add(result);
sequentialRecursive(n.getChildren(), results);
latch.countDown();
}
});

worker.start();
latch.await();

return results;
}

