import java.util.Map;
import java.util.concurrent.*;

public class SigilLedger {

    private final ReadWriteLock lock = new ReentrantReadWriteLock();
    private Map<String, Integer> runes;
    private ExecutorService executor;

    public SigilLedger(Map<String, Integer> runes) {
        this.runes = runes;
        this.executor = Executors.newFixedThreadPool(3));
    }

    public int getRuneCount() {
        return runes.size();
    }

    public boolean isEmpty() {
        lock.readLock().lock();
        try {
            return runes.isEmpty();
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean containsRune(String rune) {
        return runes.containsKey(rune);
    }

    public void putRune(String rune, Integer value) {
        executor.submit(() -> {
            lock.writeLock().lock();
            try {
                runes.put(rune, value);
            } finally {
                lock.writeLock().unlock();
            }
        }));
    }

    public Integer removeRune(String rune) {
        Future<Integer> future = executor.submit(() -> {
            lock.writeLock().lock();
            try {
                return runes.remove(rune));
            } finally {
                lock.writeLock().unlock();
            }
        }));

        try {
            return future.get();
        } catch (InterruptedException | ExecutionException e) {
            e.printStackTrace();
            return null;
        }
    }

    public void putAllRunes(Map<String, Integer> runesToAdd) {
        executor.submit(() -> {
            lock.writeLock().lock();
            try {
                runes.putAll(runesToAdd);
            } finally {
                lock.writeLock().unlock();
            }
        }));
    }

    public void clearRunes() {
        executor.submit(() -> {
            lock.writeLock().lock();
            try {
                runes.clear();
            } finally {
                lock.writeLock().unlock();
            }
        }));
    }
}

