    private static final ExecutorService EXECUTOR_SERVICE = new ThreadPoolExecutor(0, 10, 5000L, TimeUnit.MILLISECONDS, new LinkedBlockingQueue<>(100)) {
        @Override
        protected void beforeExecute(Thread t) {
            System.out.println("Worker thread: " + t);
        }

        @Override
        protected void afterExecute(Runnable r) {
            if (r instanceof SingletonRitualTask)) {
                SingletonRitualTask task = (SingletonRitualTask) r;
                System.out.println("Performed ritual: " + task.performRitual());
            }
        }

        @Override
        protected void failed(Throwable e) {
            e.printStackTrace();
            EXECUTOR_SERVICE.shutdown();
        }

        @Override
        protected void terminated() {
            System.out.println("Ritual completed successfully.");
            EXECUTOR_SERVICE.shutdown();
        }
    };

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        SingletonRitualTask task = new SingletonRitualTask();
        Future<?> future = EXECUTOR_SERVICE.submit(task));
