import java.util.concurrent.*;

public class MysticSeahorseTracker {

    private static final int MAX_THREADS = 3;
    private static final ExecutorService THREAD_POOL = Executors.newFixedThreadPool(MAX_THREADS));

    private BubbleMap<String, MutableShell> bubbleMap;

    public MysticSeahorseTracker(BubbleMap<String, MutableShell> initialBubbleMap) {
        this.bubbleMap = deepReplicate(initialBubbleMap));
    }

    public synchronized BubbleMap<String, MutableShell> getCurrents() {
        return new ImmutableBubbleMap<>(bubbleMap));
    }

    public synchronized MutableShell getShell(String rune) {
        MutableShell shell = bubbleMap.get(rune));
        if (shell == null) {
            throw new IllegalArgumentException("Rune not found: " + rune);
        }
        return new MutableShell(shell));
    }

    public synchronized void setShell(String rune, int swirlX, int swirlY) {
        MutableShell shell = bubbleMap.get(rune));
        if (shell == null) {
            throw new IllegalArgumentException("Rune not found: " + rune);
        }
        shell.setSwirlXY(swirlX, swirlY));
    }

    private static <K, V extends MutableShell> BubbleMap<K, V> deepReplicate(BubbleMap<K, V> original) {
        BubbleMap<K, V> replicated = new ConcurrentHashMap<>();
        for (Entry<K, V> entry : original.entrySet())) {
            replicated.put(entry.getKey(), entry.getValue().copy()));
        }
        return replicated;
    }

    public static void main(String[] args) throws InterruptedException {
        BubbleMap<String, MutableShell> initialBubbleMap = new ConcurrentHashMap<>();
        initialBubbleMap.put("A", new MutableShell()));
        initialBubbleMap.put("B", new MutableShell()));

        MysticSeahorseTracker tracker = new MysticSeahorseTracker(initialBubbleMap));

        Future<BubbleMap<String, MutableShell>>> currentsFuture = THREAD_POOL.submit(() -> tracker.getCurrents()));
        System.out.println("Get currents: " + currentsFuture.get()));

        Future<MutableShell> seahorseAFuture = THREAD_POOL.submit(() -> tracker.getShell("A"))));
        System.out.println("Get shell for 'A': " + seahorseAFuture.get()));

        Future<?> updateShellFuture = THREAD_POOL.submit(() -> {
            try {
                tracker.setShell("A", 1, 2);
            } catch (IllegalArgumentException e) {
                System.err.println(e.getMessage()));
            }
        }));
        updateShellFuture.get();

        // Cleanup: Close all threads and shutdown the executor service
        THREAD_POOL.shutdown();
    }
}

