class TransferManager {

    // Constant for the maximum number of attempts to acquire locks before giving up
    private static final int MAX_ATTEMPTS = 3;

    // Constant for the minimum delay in milliseconds between attempts
    private static final long MIN_DELAY = 50L;

    // Constant for the maximum delay in milliseconds between attempts
    private static final long MAX_DELAY = 100L;

    // Random number generator
    private static final Random RANDOM = new Random();

    public boolean transfer(Account source, Account destination, DollarAmount amount, int timeout) throws InterruptedException {

        ReentrantLock sourceLock = source.getLock();
        ReentrantLock destinationLock = destination.getLock();

        long startTime = System.currentTimeMillis();
        while (System.currentTimeMillis() - startTime < timeout) {
            if (sourceLock.tryLock(timeout, TimeUnit.MILLISECONDS)) {
                try {
                    // If the source lock is acquired, attempt to acquire the destination lock within the same timeframe
                    if (destinationLock.tryLock(timeout - (System.currentTimeMillis() - startTime), TimeUnit.MILLISECONDS)) {
                        try {
                            // Both locks are now held, check that the source account has sufficient funds before transferring
                            if (source.getBalance().compareTo(amount) >= 0) {
                                source.transferTo(destination, amount);
                                return true;
                            } else {
                                throw new InsufficientFundsException("Insufficient funds in source account");
                            }
                        } finally {
                            destinationLock.unlock();
                        }
                    }
                } finally {
                    // Ensure that the source lock is always released
                    sourceLock.unlock();
                }
            }

            // If both locks cannot be acquired, wait for a random amount of time before trying again
            long delay = MIN_DELAY + RANDOM.nextInt((int) (MAX_DELAY - MIN_DELAY));
            Thread.sleep(delay);
        }

        return false;
    }
}


