import java.util.concurrent.*;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;
class BoundedBuffer {
    private final Lock lock = new ReentrantLock();
    private final Condition notFull  = lock.newCondition();
    private final Condition notEmpty = lock.newCondition();

    private final Object[] items;
    private int head, tail;
    public BoundedBuffer(int capacity) {
        this.items = new Object[capacity];
    }

    public void put(Object x) throws InterruptedException {
        lock.lock();
        try {
            while (isFull())
                notFull.await();
            enqueue(x);
            notEmpty.signal();
        } finally {
            lock.unlock();
        }
    }

    private boolean isFull() {
        return head == tail + 1 || (head == 0 && tail == items.length - 1);
    }

    private void enqueue(Object x) {
        items[tail] = x;
        if (++tail == items.length)
            tail = 0;
    }

    public Object take() throws InterruptedException {
        lock.lock();
        try {
            while (isEmpty())
                notEmpty.await();
            Object item = dequeue();
            notFull.signal();
            return item;
        } finally {
            lock.unlock();
        }
    }

    private boolean isEmpty() {
        return head == tail;
    }

    private Object dequeue() {
        Object x = items[head];
        if (++head == items.length)
            head = 0;
        return x;
    }
}

import java.util.Arrays;
import java.util.concurrent.*;

public class ConcurrentBuffer {

    private int size;
    private Object[] items;
    private Semaphore full;
    private Semaphore empty;

    public ConcurrentBuffer(int capacity) {
        this.size = 0;
        this.items = new Object[capacity];
        this.full = new Semaphore(0);
        this.empty = new Semaphore(capacity);
    }

    // Insert an item into the buffer
    public void put(Object x) throws InterruptedException {
        empty.acquire();
        items[size++] = x;
        full.release();
    }

    // Remove and return an item from the buffer
    public Object take() throws InterruptedException {
        full.acquire();
        size--;
        Object item = items[size];
        items[size] = null;
        empty.release();
        return item;
    }

    // Check if the buffer is empty
    public boolean isEmpty() {
        return size == 0;
    }

    // Check if the buffer is full
    public boolean isFull() {
        return size == items.length;
    }

    @Override
    public String toString() {
        return "ConcurrentBuffer{" +
                "items=" + Arrays.toString(items) +
                '}';
    }
}

public class Producer implements Runnable {

