import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

/**
 * A custom thread class that tracks the lifecycle of application threads and provides exception handling for uncaught errors.
 * <p>
 * This is a modified version of <NAME>'s "Java Concurrency in Practice" book code example:
 * http://docs.oracle.com/javase/10/docs/api/java/lang/Thread.html
 * <p>
 * @author <NAME>, <EMAIL>
 */
public class MyAppThread extends Thread {
    // The default name prefix for threads created by this class.
    private static final String DEFAULT_NAME = "MyAppThread";

    // A static counter to assign unique thread names.
    private static final AtomicInteger nextId = new AtomicInteger(0);

    // The total number of threads created using this class, including the main thread.
    private static final AtomicLong created = new AtomicLong();

    // The current number of active application threads using this class.
    private static final AtomicLong alive = new AtomicLong();

    // A flag to indicate whether debug logging is enabled for all threads created using this class.
    private static volatile boolean debugLifecycle = false;

    // The default uncaught exception handler for application threads.
    private static UncaughtExceptionHandler unhandledExceptionLogger =
        new MyUncaughtExceptionHandler();

    // The logger used for severe errors and debug logging.
    private static Logger log = Logger.getAnonymousLogger();

    /**
     * Sets the flag to enable or disable debug logging for all threads created using this class.
     */
    public static void setDebug(boolean b) {
        debugLifecycle = b;
    }

    /**
     * Returns the total number of threads that have been created (including the main thread).
     */
    public static long getTotalCreated() {
        return created.get();
    }

    /**
     * Returns the current number of active application threads using this class.
     */
    public static int getThreadsAlive() {
        return alive.intValue();
    }

    // Initializes a new MyAppThread instance with the specified name and target runnable object, then starts it.
    private void execute(Runnable r) {
        Thread t = new Thread(r);
        log.fine("Starting thread " + t.getName());
        t.start();
    }

    /**
     * Constructs a new MyAppThread instance with no target or name.
     */
    public MyAppThread() {}

    /**
     * Constructs a new MyAppThread instance with the specified target runnable object and default name prefix.
     */
    public MyAppThread(Runnable r) {
        super(r);
        init(DEFAULT_NAME + "-" + nextId.incrementAndGet());
    }

    /**
     * Constructs a new MyAppThread instance with the specified name and target runnable object, then starts it.
     */
    public MyAppThread(String name) {
        super(name);
        init(name);
    }

    /**
     * Initializes this thread's name and sets up an uncaught exception handler for logging severe errors.
     */
    private void init(String name) {
        if (debugLifecycle)
            log.fine("Created " + name);

        created.incrementAndGet();
        setName(name);
        setUncaughtExceptionHandler(unhandledExceptionLogger);
    }

    /**
     * Logs the thread's creation and termination using the MyAppThread logger.
     */
    @Override
    public void run() {
        alive.incrementAndGet();
        try {
            super.run();
        } finally {
            alive.decrementAndGet();
        }
    }
}

/**
 * A custom uncaught exception handler that logs severe errors for application threads using the MyAppThread logger.
 */
class MyUncaughtExceptionHandler implements Thread.UncaughtExceptionHandler {

    // Logs a severe error with the thread's name and stack trace.
    @Override
    public void uncaughtException(Thread t, Throwable e) {
        Logger log = MyAppThread.log;

        log.log(Level.SEVERE, "Caught exception in thread: " + t.getName(), e);
    }
}

