            } catch (InterruptedException e) {}

            logStatus();
        };
    }

    /**
     * Returns a runnable that throws an exception and then prints its status information using the MyAppThread logger.
     */
    public static Runnable newThrowTask() {
        return () -> {
            throw new RuntimeException("Exception in thread " + Thread.currentThread().getName());
        };
    }

    public static void main(String[] args) {

        // Enable debug logging for threads created with MyAppThread.
        MyAppThread.setDebug(true);

