            }
        });

        // Create a list of tasks to be executed by the fixed thread pool.
        List<Callable<Object>> callables = Arrays.asList(newSleepTask(SLEEP_SECONDS),
                                                         newSleepTask(2 * SLEEP_SECONDS),
                                                         newThrowTask(),
                                                         () -> {
                                                             logStatus();
                                                             return null;
                                                         });

        // Submit all tasks to the executor service and retrieve their results.
