import java.util.concurrent.*;
import java.util.function.Predicate;
import java.util.stream.Collectors;
import java.util.stream.Stream;

class PrimeGenerator implements Runnable {
  private volatile boolean isCancelled = false;

  public void run() {
    // Start generating prime numbers in a separate thread for a duration of one second

    while (!isCancelled) {
      generatePrimeNumbers();

      try {
        Thread.sleep(100);
      } catch (InterruptedException e) {
        System.out.println("Thread interrupted: " + e);
      }
    }
  }

  public void start() {
    // Start the generation process using ExecutorService

    ExecutorService executorService = Executors.newSingleThreadExecutor();
    executorService.execute(this);

    try {
      Thread.sleep(1000);
    } catch (InterruptedException e) {
      System.out.println("Main thread interrupted: " + e);
    }
  }

  public void cancel() {
    // Cancel the generation process using ExecutorService and interrupt the thread if needed
    isCancelled = true;
    Thread.currentThread().interrupt();
  }

  private void generatePrimeNumbers() {
    // Generate prime numbers up to a given limit (e.g., 10)

    int upperBound = 20;

    List<Integer> primeNumbers = Stream.iterate(2, n -> n + 1)
      .limit(upperBound - 1)
      .filter(isPrime())
      .collect(Collectors.toList());

    // Store the generated prime numbers in a thread-safe list (e.g., CopyOnWriteArrayList)
    List<Integer> threadSafeList = new CopyOnWriteArrayList<>(primeNumbers);

    // Output the collected primes after generation is complete
    System.out.println("Collected primes: " + threadSafeList);
  }

  private static Predicate<Integer> isPrime() {
    return n -> {
      if (n < 2) {
        return false;
      }

      for (int i = 2; i <= Math.sqrt(n); i++) {
        if (n % i == 0) {
          return false;
        }
      }

      return true;
    };
  }
}

