class StripedMap {
    private final Node[] buckets; // Array of buckets to store key-value pairs
    private final Object[] locks; // Array of locks to synchronize access to the buckets

    public StripedMap() {
        this.buckets = new Node[16]; // Initialize with a default size of 16 buckets
        this.locks = new Object[16]; // Initialize an array of locks corresponding to the number of buckets
        for (int i = 0; i < locks.length; i++) {
            locks[i] = new Object(); // Initialize each lock object
        }
    }

    private int hash(Object key) {
        return Math.abs(key.hashCode() % buckets.length); // Hash the key to determine which bucket it belongs to
    }

    public V get(K key, V defaultValue) {
        int index = hash(key); // Get the hash index of the key
        Object lock = locks[index % locks.length]; // Get the corresponding lock object for the index
        synchronized (lock) {
            Node<K, V> node = buckets[index]; // Get the first node in the bucket at the calculated index
            while (node != null) {
                if (key.equals(node.getKey())) {
                    return node.getValue(); // Return the value of the matching key-value pair
                }
                node = node.next; // Move to the next node in the chain
            }
        }

        return defaultValue; // If no matching key found, return the default value
    }

    public void clear() {
        for (int i = 0; i < buckets.length; i++) {
            Object lock = locks[i % locks.length]; // Get the corresponding lock object for the index
            synchronized (lock) {
                buckets[i] = null; // Set the bucket at index i to null
            }
        }
    }

    private static class Node<K, V> {
