import java.math.BigInteger;
import java.util.Arrays;

public class ImmutableCache {
    private final BigInteger number;
    private final BigInteger[] factors;

    public ImmutableCache(final BigInteger number) {
        this.number = number;
        this.factors = findFactors(number);
    }

    public ImmutableCache(final BigInteger number, final BigInteger... factors) {
        this.number = number;
        this.factors = Arrays.copyOf(factors, factors.length);
    }

    private static BigInteger[] findFactors(BigInteger number) {
        if (number.compareTo(BigInteger.ZERO) <= 0 || !number.isProbablePrime(1)) {
            return new BigInteger[0];
        }

        final var result = new BigInteger[]{BigInteger.ONE, number};
        while (!number.equals(BigInteger.ONE)) {
            for (var factor : number.primeFactors()) {
                if (number.mod(factor).equals(BigInteger.ZERO)) {
                    number = number.divide(factor);
                    if (!Arrays.stream(result).anyMatch(f -> f.equals(factor))) {
                        result[0] = result[0].multiply(factor);
                        result = Arrays.copyOf(result, result.length + 1);
                        result[result.length - 1] = factor;
                    }
                }
            }
        }

        return Arrays.copyOfRange(result, 2, result.length);
    }

    public BigInteger[] getFactors() {
        if (number.equals(this.number)) {
            return factors.clone();
        } else {
            return null;
        }
    }
