    public DollarAmount subtract(DollarAmount other) throws InsufficientFundsException {
        if (other.amountInCents > this.amountInCents)
            throw new InsufficientFundsException();
        return new DollarAmount(this.amountInCents - other.amountInCents);
    }

    // Check whether the amount in this object is less than or equal to another DollarAmount object's amount.
    public boolean lessThanOrEqual(DollarAmount other) {
        return this.amountInCents <= other.amountInCents;
    }
}


