        return balance;
    }

    @Override
    public void transfer(Account other, DollarAmount amount) throws InsufficientFundsException {
        synchronized (this) {
            // Determine the order in which to acquire locks based on the object's identity hash code.
            Account first = this.hashCode() < other.hashCode() ? this : other;
            Account second = first == this ? other : this;

            try {
                // Acquire the lock of the first account and wait if it is already acquired by another thread.
                first.wait();

                // Acquire the lock of the second account and wait if it is already acquired by another thread.
                synchronized (second) {
                    second.wait();

                    // Perform a transfer from this account to the other account, which involves debiting this account and crediting the other account.
                    balance = balance.subtract(amount);
                    other.deposit(amount);

                    // Notify all threads that are waiting on the first account's lock.
                    first.notifyAll();
                }

                // Notify all threads that are waiting on the second account's lock.
                second.notifyAll();
            } catch (InterruptedException e) {
                throw new RuntimeException("Interrupted while waiting for locks");
            }
        }
    }

    // Deposit funds into this account by adding an amount to its balance.
    public void deposit(DollarAmount amount) {
