import java.util.concurrent.atomic.AtomicReference;

public class ConcurrentStack {

    private static class Node {
        int value;
        Node next;

        public Node(int v, Node n) {
            this.value = v;
            this.next = n;
        }
    }

    private AtomicReference<Node> top;

    public ConcurrentStack() {
        // Initialize an empty stack with null top reference
        top = new AtomicReference<>(null);
    }

    public void push(int value) {
        Node newNode = new Node(value, null);

        while (true) {
            // Get current top node reference
            Node currentTop = top.get();

            // Set the new node's next to point to the current top node
            newNode.next = currentTop;

            // Attempt to update the top of the stack with the new node using CAS
            if (top.compareAndSet(currentTop, newNode)) {
                // Update successful - break out of the loop
                break;
            }
        }
    }

    public Node pop() {
        while (true) {
            // Get current top node reference
            Node currentTop = top.get();

            // If stack is empty, return null
            if (currentTop == null) {
                return null;
            }

            // Attempt to update the top of the stack with its next node using CAS
            if (top.compareAndSet(currentTop, currentTop.next)) {
                // Update successful - return the old top node
                return currentTop;
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        ConcurrentStack stack = new ConcurrentStack();

        // Create and start 3 additional threads to perform push/pop operations concurrently
        Thread thread1 = new Thread(() -> {
            for (int i = 0; i < 5; i++) {
                stack.push(i);
            }
            for (int i = 0; i < 5; i++) {
                Node poppedNode = stack.pop();
                if (poppedNode != null) {
                    System.out.println("Thread 1: Popped node with value " + poppedNode.value);
                } else {
                    System.out.println("Thread 1: Stack empty");
                }
            }
        });
        Thread thread2 = new Thread(() -> {
            for (int i = 0; i < 5; i++) {
                stack.push(i * 10);
            }
            for (int i = 0; i < 5; i++) {
                Node poppedNode = stack.pop();
                if (poppedNode != null) {
                    System.out.println("Thread 2: Popped node with value " + poppedNode.value);
                } else {
                    System.out.println("Thread 2: Stack empty");
                }
            }
        });
        Thread thread3 = new Thread(() -> {
            for (int i = 0; i < 5; i++) {
                stack.push(i * 100);
            }
            for (int i = 0; i < 5; i++) {
                Node poppedNode = stack.pop();
                if (poppedNode != null) {
                    System.out.println("Thread 3: Popped node with value " + poppedNode.value);
                } else {
                    System.out.println("Thread 3: Stack empty");
                }
            }
        });

        // Start the threads and wait for them to finish
        thread1.start();
        thread2.start();
        thread3.start();
        thread1.join();
        thread2.join();
        thread3.join();

        System.out.println("All threads finished.");
    }
}

import java.util.*; 
import java.util.concurrent.atomic.*; 
 class ConcurrentStack {
    private static class Node<T> {
        T item; 
        AtomicReference<Node<T>> next; 
        public Node(T item, Node<T> next) {
            this.item = item; 
            this.next = new AtomicReference<>(next); }
        }
        private AtomicReference<Node<T>> top = new AtomicReference<>(); 

        public void push(T item) {
            Node<T> node = new Node<>(item, null); 
            while (true) {
                Node<T> currentTop = top.get(); 
                node.next.set(currentTop); 
                if (top.compareAndSet(currentTop, node)) 
                    break; 
                }
            }

        public T pop() {
            while (true) {
                Node<T> currentTop = top.get(); 
                if (currentTop == null) return null; 
                if (top.compareAndSet(currentTop, currentTop.next.get())) 
                    return currentTop.item; 
                }
        }

    public static void main(String[] args) throws InterruptedException {
        ConcurrentStack stack = new ConcurrentStack<>(); 
        ExecutorService executor = Executors.newFixedThreadPool(3); 
        Runnable pushTask = () -> {
            for (int i = 1; i <= 5; i++) {
                stack.push(i); 
                System.out.println("Pushed: " + i); 
            }
        };
        Runnable popTask = () -> {
            for (int i = 0; i < 5; i++) {
                Integer item = stack.pop(); 
                if (item == null) 
                    break; 
                System.out.println("Popped: " + item); 
            }
        };
        executor.submit(pushTask); 
        executor.submit(popTask); 
        executor.shutdown(); 
        executor.awaitTermination(10, TimeUnit.SECONDS); 
        System.out.println("Done!"); 
    }
}

