import java.util.*;
import java.util.concurrent.*;

public class DelegatingVehicleTracker {
    private final ConcurrentHashMap<String, String> locations;

    public DelegatingVehicleTracker(Map<String, String> locations) {
        this.locations = new ConcurrentHashMap<>(locations);
    }

    public synchronized void setLocation(String id, String location) {
        if (locations.containsKey(id)) {
            locations.put(id, location);
        }
    }

    public synchronized String getLocation(String id) {
        return locations.get(id);
    }

    public Map<String, String> getLocations() {
        // Use a live view of the map to avoid synchronization issues with the caller.
        return Collections.unmodifiableMap(locations);
    }

    public static void main(String[] args) {
        Map<String, String> initialLocations = new HashMap<>();
        initialLocations.put("vehicle1", "locationA");
        initialLocations.put("vehicle2", "locationB");

        DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(initialLocations);
        System.out.println("Initial Locations: " + tracker.getLocations());

        // Create a thread pool for managing threads
        ExecutorService executor = Executors.newFixedThreadPool(2);

        // Set the location of vehicle1 in another thread
