import java.util.*;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicInteger;

public class Main {
    static enum Gender {
        MALE, FEMALE
    }

    // Represents an animal
    public record Animal(String species, String name, Gender gender) {}

    // Custom comparator for sorting Animals by species and then gender
    private static final Comparator<Animal> COMPARATOR_BY_SPECIES_AND_GENDER = (a1, a2) -> {
        int speciesDiff = a1.species().compareTo(a2.species());

        if (speciesDiff != 0) {
            return speciesDiff;
        } else {
            // Sort by gender
            return a1.gender().compareTo(a2.gender());
        }
    };

    private static final Comparator<Animal> COMPARATOR_BY_GENDER = (a1, a2) -> {
        int speciesDiff = a1.gender().compareTo(a2.gender());

        if (speciesDiff != 0) {
            return speciesDiff;
        } else {
            // Sort by gender
            return a1.species().compareTo(a2.species());
        }
    };

    // Represents a pair of animals that can be loaded onto an ark
    public record Pair(Animal animal1, Animal animal2) {}

    private static final ExecutorService executor = Executors.newFixedThreadPool(2);
    private static final AtomicInteger count = new AtomicInteger();

    // Sorts the list of animals by species and gender using a custom comparator
    private static List<Animal> sortAnimalsBySpeciesAndGender(List<Animal> animals) {
        Collections.sort(animals, COMPARATOR_BY_SPECIES_AND_GENDER);

        return animals;
    }

    // Sorts the list of pairs by gender using a custom comparator
    private static List<Pair> sortPairsbyGender(List<Pair> pairs) {
        Collections.sort(pairs, (p1, p2) -> COMPARATOR_BY_GENDER.compare(p1.animal1(), p2.animal1()));

        return pairs;
    }

    // Generates a list of valid animal pairs based on species and gender compatibility
    private static List<Pair> generateValidPairs(List<Animal> sortedAnimals) {
        List<Pair> validPairs = new ArrayList<>();
        Map<String, Pair> mapOfPairs = new HashMap<>();

        for (int i = 0; i < sortedAnimals.size(); i++) {
            Animal currentAnimal = sortedAnimals.get(i);

            if (!mapOfPairs.containsKey(currentAnimal.species())) {
                // Create a new pair with the current animal and store it in the map
                Pair newPair = new Pair(currentAnimal, null);
                mapOfPairs.put(currentAnimal.species(), newPair);
            } else {
                // Get the existing pair from the map and complete it
                Pair existingPair = mapOfPairs.get(currentAnimal.species());

                if (existingPair.animal2() == null) {
                    // Set the second animal of the pair
                    existingPair.animal2().setName(currentAnimal.name());

                    validPairs.add(existingPair);
                }
            }
        }

        return sortPairsbyGender(validPairs);
    }

    private static void loadTheArk(List<Animal> candidates) {
        // Load all animals onto the ark
        List<Animal> sortedAnimals = sortAnimalsBySpeciesAndGender(candidates);

        // Count the number of valid pairs
        count.set(generateValidPairs(sortedAnimals).size());
    }

    private static void printResult() {
        executor.execute(() -> {
            while (true) {
                try {
                    System.out.println("Count: " + count.get());
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    // Ignore interrupt exception
                }
            }
        });
    }

    public static void main(String[] args) throws InterruptedException {
        List<Animal> candidates = new ArrayList<>();

        for (int i = 0; i < 5; i++) {
            candidates.add(new Animal("Lion", "Lion" + i, Gender.values()[i % 2]));
            candidates.add(new Animal("Tiger", "Tiger" + i, Gender.values()[i % 2]));
        }

        // Create a thread to print the result
        executor.execute(() -> {
            while (true) {
                try {
                    System.out.println("Count: " + count.get());
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    // Ignore interrupt exception
                }
            }
        });

        loadTheArk(candidates);
    }
}

