    private static void loadTheArk(List<Animal> animalList) {
        Collections.sort(animalList, (a1, a2) -> {
            // Sort by species and then gender
            if (a1.getSpecies().equals(a2.getSpecies())) {
                return a1.getGender().compareTo(a2.getGender());
            } else {
                return a1.getSpecies().compareTo(a2.getSpecies());
            }
        });

        // Group animals by species and gender
        Map<Pair, List<Animal>> groups = new HashMap<>();
        for (int i = 0; i < animalList.size(); i++) {
