            Species species = animal.getSpecies();
            Gender gender = animal.getGender();

            Pair groupKey = new Pair(species, gender);

            List<Animal> groupList = groups.computeIfAbsent(groupKey, k -> new ArrayList<>());
            groupList.add(animal);
        }

        // Pair animals with compatible species and opposite genders
        int validPairsCount = 0;
        for (Map.Entry<Pair, List<Animal>> entry : groups.entrySet()) {
            List<Animal> groupList = entry.getValue();

            if (groupList.size() > 1) {
                // Pair animals within the group

                Animal firstAnimal = groupList.get(0);
                Animal secondAnimal = groupList.get(1);
