import java.util.*;
import java.util.concurrent.*;

public class Ark {
    public enum Gender {
        MALE, FEMALE
    }

    public enum Species {
        BEAR, HIPPO, LION, PANDA
    }

    private static class Animal {
        public final Species species;
        public final Gender gender;

        public Animal(Species species, Gender gender) {
            this.species = species;
            this.gender = gender;
        }
    }

    private static class Pair {
        public final Animal first;
        public final Animal second;

        public Pair(Animal first, Animal second) {
            this.first = first;
            this.second = second;
        }
    }

    private static class Ark {
        private List<Pair> pairs;

        public Ark() {
            this.pairs = new ArrayList<>();
        }

        public void add(Pair pair) {
            synchronized (this) {
                pairs.add(pair);
            }
        }

        public int size() {
            return pairs.size();
        }
    }

    private static class PairingComparator implements Comparator<Animal> {
        @Override
        public int compare(Animal a, Animal b) {
            if (!a.species.equals(b.species)) {
                // Sort by species first
                return a.species.compareTo(b.species);
            } else {
                // Then sort by opposite gender
                return -1 * a.gender.compareTo(b.gender);
            }
        }
    }

    public static int loadTheArk(Collection<Animal> animals) throws InterruptedException, ExecutionException {
        Ark ark = new Ark();

        ExecutorService executor = Executors.newFixedThreadPool(3);
        List<Callable<Void>> tasks = new ArrayList<>();

        // Sort the animals by species and gender compatibility for pairing
        List<Animal> sortedAnimals = new ArrayList<>(animals);
        Collections.sort(sortedAnimals, new PairingComparator());

        // Process each pair of animals in parallel
        int index = 0;
        while (index < sortedAnimals.size()) {
            Animal a1 = sortedAnimals.get(index++);
            if (a1 == null) continue;
            Animal a2 = sortedAnimals.get(index++);
            if (a2 == null) break;

            // Create the pairing task and add it to the executor's queue
            tasks.add(() -> {
                ark.add(new Pair(a1, a2));
                return null;
            });
        }

        executor.invokeAll(tasks);
        executor.shutdown();

        // Return the number of pairs formed
        return ark.size();
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        List<Animal> animals = new ArrayList<>();
        animals.add(new Animal(Species.BEAR, Gender.FEMALE));
        animals.add(new Animal(Species.HIPPO, Gender.MALE));
        animals.add(new Animal(Species.LION, Gender.MALE));
        animals.add(new Animal(Species.PANDA, Gender.FEMALE));

        int pairsFormed = loadTheArk(animals);
        System.out.println("Pairs formed: " + pairsFormed);
    }
}

