import java.util.concurrent.*;

/**
* TestHarness
*
* Using CountDownLatch to control the start and stop of threads in timing tests.
*
* @author Brian Goetz and Tim Peierls
*/
public class TestHarness {
public long timeTasks(int nThreads, final Runnable task) throws InterruptedException {
final CountDownLatch startGate = new CountDownLatch(1);
final CountDownLatch endGate = new CountDownLatch(nThreads);

for (int i = 0; i < nThreads; i++) {
Thread t = new Thread(() -> {
try {
startGate.await();
try {
task.run();
} finally {
endGate.countDown();
}
} catch (InterruptedException e) {
Thread.currentThread().interrupt();
}
});
t.start();
}

long start = System.nanoTime();
startGate.countDown(); // Allow all threads to start running
endGate.await(); // Wait for all threads to finish
long end = System.nanoTime();
return end - start;
}

public static void main(String[] args) throws InterruptedException {
TestHarness harness = new TestHarness();

// Define a simple task: sleep for a while
Runnable task = () -> {
try {
System.out.println(Thread.currentThread().getName() + " is running.");
Thread.sleep(1000); // Simulate a time-consuming operation
} catch (InterruptedException e) {
Thread.currentThread().interrupt();
}
};

int nThreads = 2; // Run with 2 threads
long duration = harness.timeTasks(nThreads, task);

System.out.printf("All %d tasks completed in %.3f seconds.%n",
nThreads, duration / 1_00.0);
}
}

