public class BoundedHashSet<T> {
    private final Set<T> set;
    private final Semaphore semaphore;

    public BoundedHashSet(int bound) {
        this.set = Collections.synchronizedSet(new HashSet<>());
        this.semaphore = new Semaphore(bound);
    }

    public boolean add(T o) {
        try {
            semaphore.acquire();
            return set.add(o);
        } catch (InterruptedException e) {
            throw new RuntimeException("Interrupted while adding element to BoundedHashSet", e);
        } finally {
            if (!set.contains(o))
                semaphore.release();
        }
    }

    public boolean remove(Object o) {
        try {
            return set.remove(o);
        } finally {
            semaphore.release();
        }
    }
}

ground_truth:
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.Semaphore;

public class BoundedHashSet<T> {
private final Set<T> set;
private final Semaphore sem;

public BoundedHashSet(int bound) {
this.set = Collections.synchronizedSet(new HashSet<>());
this.sem = new Semaphore(bound);
}

public boolean add(T o) throws InterruptedException {
sem.acquire();
boolean added = set.add(o);
if (!added) {
sem.release();
}
return added;
}

public boolean remove(Object o) {
boolean removed = set.remove(o);
if (removed) {
sem.release();
}
return removed;
}

public int size() {
return set.size();
}

public static void main(String[] args) throws InterruptedException {
final BoundedHashSet<String> boundedSet = new BoundedHashSet<>(2);

Thread t1 = new Thread(() -> {
try { boundedSet.add("A"); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
});

Thread t2 = new Thread(() -> {
try { boundedSet.add("B"); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
});

Thread t3 = new Thread(() -> {
try { boundedSet.add("C"); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
});

t1.start(); t2.start(); t1.join(); t2.join();

boundedSet.remove("A");

t3.start(); t3.join();

System.out.println("Final set size: " + boundedSet.size());
}
}

