import java.util.*;
import java.util.concurrent.*;

public class Main {
    public static void main(String[] args) throws InterruptedException, ExecutionException {
        ExecutorService executor = Executors.newSingleThreadExecutor();

        try {
            Future<List<Integer>> primeGeneratorFuture = executor.submit(() -> generatePrimeNumbers());

            Thread.sleep(1000);
            if (primeGeneratorFuture != null && !primeGeneratorFuture.isDone())
                primeGeneratorFuture.cancel(true);
        } finally {
            executor.shutdownNow();
        }
    }

    private static List<Integer> generatePrimeNumbers() throws InterruptedException, ExecutionException {
        Random random = new Random();

        final int PRIMES_TO_GENERATE = 10;
        List<Integer> primes = Collections.synchronizedList(new ArrayList<>());

        // Create a FutureTask to asynchronously execute the prime number generation task
        Future<?> futureTask = Executors.newSingleThreadExecutor().submit(() -> {
            for (int i = 0; i < PRIMES_TO_GENERATE; i++) {
                int candidate = random.nextInt(25) + 1; // Generate a random number between 1 and 25

                while (!primes.contains(candidate)) {
                    boolean isPrime = true;

                    for (int j = 2; j < candidate; j++) {
                        if (candidate % j == 0) {
                            isPrime = false;
                            break;
                        }
                    }

                    if (isPrime) {
                        primes.add(candidate);
                        break;
                    } else {
                        candidate++; // Increment the number to check for primality
                    }
                }
            }
        });

        futureTask.get(); // Wait for the prime number generation task to finish

        return primes;
    }
}

