class GeneratePrimesTask implements Runnable {
    private volatile boolean cancelled = false;

    public void cancel() {
        this.cancelled = true;
    }

    @Override
    public void run() {
        List<Long> primes = new ArrayList<>();
        long counter = 2;

        while (!this.cancelled) {
            if (isPrime(counter)) {
                synchronized (primes) {
                    primes.add(counter);
                }
            }

            // Increment the counter by one to check the next number
            counter++;
        }
    }

    private boolean isPrime(long n) {
        if (n <= 1) return false;

        for (int i = 2; i < Math.sqrt(n) + 1; i++) {
            if (n % i == 0) {
                // Number is not prime
                return false;
            }
        }

        // Number is prime
        return true;
    }

    public List<Long> getPrimes() {
        synchronized (primes) {
            return new ArrayList<>(primes);
        }
    }
}


