import java.util.concurrent.*;
public class PrimeProducer extends Thread {
    BlockingQueue < Integer > queue;
    int primeLimit = 1000000;
    private boolean isRunning = true;

    public PrimeProducer(BlockingQueue < Integer > queue) {
        this.queue = queue;
    }

    @Override
    public void run() {
        try {
            producePrimes();
        } catch (InterruptedException e) {}
    }

    public synchronized int[] generatePrimeArray() throws InterruptedException {

        // Define a boolean array to hold the primality status of all numbers
        boolean isNotPrime[] = new boolean[primeLimit + 1];
        int primeCount = 0;
        int totalPrimesGenerated = 0;

        // Set all indices to false, since no number is known to be composite yet
        for (int i = 0; i <= primeLimit; ++i) {
            isNotPrime[i] = false;
        }

        // A value of zero or one cannot be prime. Set their indices to true
        isNotPrime[0] = true;
        isNotPrime[1] = true;

        int[] allPrimes = new int[primeLimit];
        for (int i = 2; i <= primeLimit && totalPrimesGenerated < 2; ++i) {

            // If the current number has not been determined to be composite
            if (!isNotPrime[i]) {

                // Increment our count of prime numbers
                allPrimes[primeCount] = i;
                primeCount++;
                totalPrimesGenerated++;

                for (int j = i * 2; j <= primeLimit; j += i)
                    isNotPrime[j] = true;
            }
        }

        return allPrimes;
    }

    private void producePrimes() throws InterruptedException {

        while (!isInterrupted()) {

            try {
                int[] primes = generatePrimeArray();

                queue.put(primes[0]);
                queue.put(primes[1]);
            } catch (InterruptedException e) {}
        }
    }
}
