        // Create a list of Callable objects that perform processing on each number in parallel
        List<Callable<Double>> tasks = numbers.stream()
                .map(number -> (Callable<Double>) () -> processNumberParallel(number))
                .collect(Collectors.toList());

        // Submit the tasks to the executor and wait for them to complete
        List<Future<Double>> futures = executor.invokeAll(tasks);

        // Retrieve the results from each future and return them in a list
        List<Double> results = new ArrayList<>();
        for (Future<Double> future : futures) {
            results.add(future.get());
        }

        executor.shutdown();

        return results;
    }

    private static Double processNumberParallel(int number) {
        // Perform some parallel processing on the number and return the result
        return 2.0 * number + 1;
    }

    private static void printResults(List<Double> results) {
        for (double result : results) {
            System.out.println(result);
        }
    }
}

